import React from 'react';

const Answer = ({
    question,
    options,
    selectedAnswer,
    correctAnswer,
    hint,
    explanation,
    difficulty,
    subject,
    topic
}) => {
    return (
        <div className="bg-white shadow-lg rounded-lg p-4 mb-6 border border-gray-200">
            <div className="mb-4">
                <h3 className="text-xl font-semibold text-gray-800">Question:</h3>
                <p className="text-gray-600 mt-2">{question}</p>
            </div>

            <div className="mb-4">
                <h4 className="text-lg font-semibold text-gray-800">Options:</h4>
                <ul className="mt-2 space-y-2">
                    {options.map((option, index) => (
                        <li
                            key={index}
                            className={`px-4 py-2 rounded-lg ${
                                index === selectedAnswer
                                    ? index === correctAnswer
                                        ? 'bg-green-100 border border-green-600'
                                        : 'bg-red-100 border border-red-600'
                                    : ''
                            }`}
                        >
                            {index + 1}. {option}
                        </li>
                    ))}
                </ul>
            </div>

            <div className="mb-4">
                <span className="font-semibold text-gray-800">Correct Answer: </span>
                <span className="text-green-600">{options[correctAnswer]}</span>
            </div>

            {selectedAnswer !== undefined && (
                <div className={`font-semibold mt-4 ${selectedAnswer === correctAnswer ? 'text-green-600' : 'text-red-600'}`}>
                    {selectedAnswer === correctAnswer ? 'Correct!' : 'Incorrect'}
                </div>
            )}

            {hint && (
                <div className="mt-4">
                    <h4 className="font-semibold text-gray-800">Hint:</h4>
                    <p className="text-gray-600">{hint}</p>
                </div>
            )}

            {explanation && (
                <div className="mt-4">
                    <h4 className="font-semibold text-gray-800">Explanation:</h4>
                    <p className="text-gray-600">{explanation}</p>
                </div>
            )}

            <div className="mt-4 grid grid-cols-2 gap-4">
                <div>
                    <span className="font-semibold text-gray-800">Difficulty: </span>
                    <span className="text-gray-600 capitalize">{difficulty}</span>
                </div>
                <div>
                    <span className="font-semibold text-gray-800">Subject: </span>
                    <span className="text-gray-600">{subject}</span>
                </div>
                <div>
                    <span className="font-semibold text-gray-800">Topic: </span>
                    <span className="text-gray-600">{topic}</span>
                </div>
            </div>
        </div>
    );
};

export default Answer;
